from pathlib import Path
import subprocess,json,gzip,datetime,hashlib,sys
p=Path(__file__).resolve().parent;r=p.parents[2]
def sha(f):
 h=hashlib.sha256()
 with f.open('rb') as stream:
  for block in iter(lambda:stream.read(1024*1024),b''):h.update(block)
 return h.hexdigest()
cases={'constant-chain': '#show "B": [BB]\n#show "A": [B]\nA', 'constant-chain-inverse': '#show "A": [B]\n#show "B": [BB]\nA', 'function-chain': '#show "B":it=>[BB]\n#show "A":it=>[B]\nA', 'function-chain-inverse': '#show "A":it=>[B]\n#show "B":it=>[BB]\nA', 'alias-chain': '#let saved=[B]\n#show "B":it=>[BB]\n#show "A":it=>saved\nA', 'alias-chain-inverse': '#let saved=[B]\n#show "A":it=>saved\n#show "B":it=>[BB]\nA', 'cycle': '#show "A":it=>[B]\n#show "B":it=>[A]\nA', 'constant-cycle': '#show "A": [B]\n#show "B": [A]\nA', 'revoked-cross': '#show "C":it=>[A]\n#show "AB":it=>[X]\nCB', 'revoked-cross-inverse': '#show "AB":it=>[X]\n#show "C":it=>[A]\nCB', 'local-cross': '#let part={show "C":it=>[A];[C]}\n#show "AB":it=>[X]\n#part;B', 'leftmost': '#show "A":it=>[L]\n#show "B":it=>[R]\nAB', 'unicode-overlap': '#show "éX":it=>[L]\n#show "é":it=>[R]\néX', 'multiple-matches': '#show "A":it=>[AA]\n#show "B":it=>[BB]\nABAB', 'show-set': '#show "A":set text(fill:red)\nA', 'none-definition': '#let c=[#let x=1;A]\n#repr(c.children)', 'none-assert': '#let c=[#assert(true)A]\n#repr(c.children)', 'none-explicit': '#let c=[#none#[]A]\n#repr(c.children)', 'none-only': '#let c=[#none]\n#repr((c.func(),c.fields()))', 'identical-literals': '#show "A":it=>[C]\n#show "A":it=>[B]\nA', 'mixed-regex-literal': '#show regex("A"):it=>[R]\n#show "A":it=>[L]\nA', 'mixed-literal-regex': '#show "A":it=>[L]\n#show regex("A"):it=>[R]\nA', 'overlap': '#show "AB":it=>[X]\n#show "A":it=>[Y]\nAB', 'leftmost-effect': '#show "A":it=>panic("LATER")\n#show "Z":it=>panic("FIRST")\nZA', 'leftmost-regex-effect': '#show regex("A"):it=>panic("LATER")\n#show regex("Z"):it=>panic("FIRST")\nZA', 'same-guard-adjacent': '#show "AAAA":it=>[X]\n#show "A":it=>[AA]\nAA', 'same-guard-regex-adjacent': '#show "AB":it=>[X]\n#show regex("A|B"):it=>it\nAB', 'different-guard-adjacent': '#show "AB":it=>[X]\n#show "C":it=>[A]\n#show "D":it=>[B]\nCD', 'product-whole-group': '#show "AB":it=>[X]\n#show "C":it=>[AB]\nC', 'product-separate-nodes': '#show "AB":it=>[X]\n#show "C":it=>[A]+[B]\nC', 'constant-revoked-cross': '#show "C":[A]\n#show "AB":[X]\nCB', 'new-rule-on-completed': '#let c={show "A":it=>[B];[A]}\n#show "B":it=>[C]\n#c', 'new-rule-cross-completed': '#let c={show "C":it=>[A];[C]}\n#show "AB":it=>[X]\n#c;B', 'func-alias-raw-output': '#let saved=[B]\n#show "B":it=>[BB]\n#show "A":it=>saved\nA', 'white-text': '#show " ":it=>[S]\n#text(" ")', 'white-text-callback': '#show "A":it=>[ ]\n#show " ":it=>[S]\nA', 'white-input-normalization': '#show " ":it=>[S]\n#([ ]+[ ])', 'product-parent-hides-text': '#show "B":it=>panic("HIDDEN")\n#show strong:it=>[Q]\n#show "A":it=>strong[B]\nA', 'product-parent-hides-constant': '#let saved=strong[B]\n#show "B":it=>panic("HIDDEN")\n#show strong:it=>[Q]\n#show "A":it=>saved\nA', 'local-cjk': '#let c=[#show "水果":it=>[X]\n水\n果]\n#c', 'identity-shared-rule': '#show "A":it=>it\n#([A]+[A])', 'constant-style': '#show "B":set text(fill:red)\n#show "A":[B]\nA', 'function-style': '#show "B":set text(fill:red)\n#show "A":it=>[B]\nA', 'constant-invalid-output': '#show "A":it=>1\nA'}
bins={'tekt':r/'target/debug/typst','vanilla':r/'lab/typst-original/target/release/typst'}
meta={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'head':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'diffstat':subprocess.check_output(['git','diff','HEAD','--stat'],text=True),'status':subprocess.check_output(['git','status','--porcelain=v1','--untracked-files=all'],text=True),'binaries':{k:{'path':str(b),'sha256':sha(b)} for k,b in bins.items()},'pin':'bd5ebec285505889e8ff1d4f68804ab147a699f3','cases':[]}
for label,source in cases.items():
 f=p/'outputs'/f'{label}.typ';f.write_text(source);row={'label':label,'source':source,'source_sha256':sha(f),'results':{}}
 for name,binary in bins.items():
  out=f.with_name(f.stem+'-'+name+'.pdf');cmd=[str(binary),'compile',str(f),str(out)];z=subprocess.run(cmd,text=True,capture_output=True,timeout=45);txt=subprocess.check_output(['pdftotext',str(out),'-'],text=True) if not z.returncode else ''
  row['results'][name]={'command':cmd,'exit':z.returncode,'stderr':z.stderr,'text':' '.join(txt.split())}
 meta['cases'].append(row);print(label,[(k,v['exit'],v['text'] if not v['exit'] else v['stderr'].splitlines()[0]) for k,v in row['results'].items()],flush=True)
assert all(sha(b)==meta['binaries'][n]['sha256'] for n,b in bins.items())
(p/(sys.argv[1]+'.json.gz')).write_bytes(gzip.compress(json.dumps(meta,indent=2).encode()))
